# Phase 0 测试地图文件：发布 WMS / WMTS / WFS（EPSG:4326）
# 用法：mapserv -nh "map=/home/hatch/workspace/gis-replicate/phase0/phase0.map&SERVICE=WMS&REQUEST=GetCapabilities"
MAP
  NAME "phase0"
  STATUS ON
  SIZE 800 600
  EXTENT 116.30 39.85 116.50 40.00
  UNITS DD
  SHAPEPATH "/home/hatch/workspace/gis-replicate/phase0/data"
  PROJECTION
    "init=epsg:4326"
  END
  IMAGETYPE PNG

  WEB
    IMAGEPATH "/tmp/ms_tmp/"
    IMAGEURL "/tmp/"
    METADATA
      "wms_title"           "Phase0 Test WMS"
      "wms_onlineresource"  "http://localhost:8080/cgi-bin/mapserv?map=/home/hatch/workspace/gis-replicate/phase0/phase0.map"
      "ows_onlineresource"  "http://localhost:8080/cgi-bin/mapserv?map=/home/hatch/workspace/gis-replicate/phase0/phase0.map"
      "wfs_onlineresource"  "http://localhost:8080/cgi-bin/mapserv?map=/home/hatch/workspace/gis-replicate/phase0/phase0.map"
      "wms_srs"             "EPSG:4326 EPSG:3857"
      "wms_enable_request"  "*"
      "wfs_title"           "Phase0 Test WFS"
      "wfs_enable_request"  "*"
      "wfs_srs"             "EPSG:4326"
      "wmts_enable_request" "*"
    END
  END

  LAYER
    NAME "base_raster"
    TYPE RASTER
    STATUS ON
    DATA "test_raster.tif"
    PROJECTION
      "init=epsg:4326"
    END
    METADATA
      "wms_title" "Base raster"
      "wms_srs"   "EPSG:4326"
    END
  END

  LAYER
    NAME "parks"
    TYPE POLYGON
    STATUS ON
    CONNECTIONTYPE OGR
    CONNECTION "parks.geojson"
    PROJECTION
      "init=epsg:4326"
    END
    METADATA
      "wms_title"         "Parks"
      "wfs_title"         "Parks"
      "gml_include_items" "all"
      "wms_include_items" "all"
    END
    CLASS
      NAME "Parks"
      STYLE
        COLOR 120 200 120
        OUTLINECOLOR 30 120 30
        WIDTH 2
      END
    END
  END

  LAYER
    NAME "parks_pg"
    TYPE POLYGON
    STATUS ON
    CONNECTIONTYPE POSTGIS
    CONNECTION "host=127.0.0.1 dbname=gisdb user=gis password=gis port=5432"
    DATA "wkb_geometry FROM parks USING UNIQUE ogc_fid USING SRID=4326"
    PROJECTION
      "init=epsg:4326"
    END
    METADATA
      "wms_title"         "Parks (PostGIS)"
      "wfs_title"         "Parks (PostGIS)"
      "gml_include_items" "all"
      "wms_include_items" "all"
    END
    CLASS
      NAME "Parks (PostGIS)"
      STYLE
        COLOR 100 150 220
        OUTLINECOLOR 20 60 140
        WIDTH 2
      END
    END
  END

  LAYER
    NAME "roads"
    TYPE LINE
    STATUS ON
    CONNECTIONTYPE OGR
    CONNECTION "roads.geojson"
    PROJECTION
      "init=epsg:4326"
    END
    METADATA
      "wms_title"         "Roads"
      "wfs_title"         "Roads"
      "gml_include_items" "all"
      "wms_include_items" "all"
    END
    CLASS
      NAME "Roads"
      STYLE
        COLOR 220 60 60
        WIDTH 3
      END
    END
  END

END
